from miner3_20260730_harness import ASSETS, evaluate, load_closes
import numpy as np, pandas as pd

closes = load_closes()

def load_ohlc():
    out={}
    for a in ASSETS:
        df=pd.read_csv(f'../persistent/stock_data/{a}.csv',parse_dates=['date']).sort_values('date')
        df=df[df['date']<='2026-07-29']
        out[a]=df.set_index('date')
    return out
ohlc=load_ohlc()

def upper_shadow(df,n=20):
    hi=df['high'].astype(float); lo=df['low'].astype(float)
    op=df['open'].astype(float); cl=df['close'].astype(float)
    rng=(hi-lo).replace(0,np.nan)
    sh=(hi-np.maximum(op,cl))/rng
    return sh.rolling(n,min_periods=10).mean()
def lower_shadow(df,n=20):
    hi=df['high'].astype(float); lo=df['low'].astype(float)
    op=df['open'].astype(float); cl=df['close'].astype(float)
    rng=(hi-lo).replace(0,np.nan)
    sh=(np.minimum(op,cl)-lo)/rng
    return sh.rolling(n,min_periods=10).mean()
def shadow_asym(df,n=20):
    return upper_shadow(df,n)-lower_shadow(df,n)
def body_pos(df,n=20):
    hi=df['high'].astype(float); lo=df['low'].astype(float)
    op=df['open'].astype(float); cl=df['close'].astype(float)
    rng=(hi-lo).replace(0,np.nan)
    return ((cl-op)/rng).rolling(n,min_periods=10).mean()
def up_down_body_ratio(df,n=20):
    hi=df['high'].astype(float); lo=df['low'].astype(float)
    op=df['open'].astype(float); cl=df['close'].astype(float)
    rng=(hi-lo).replace(0,np.nan)
    body=(cl-op)/rng
    return body.rolling(n,min_periods=10).sum()/ (body.rolling(n,min_periods=10).apply(lambda x:(np.abs(x)).sum())).replace(0,np.nan)

