 'lower_shadow_20d':{a:lower_shadow(ohlc[a],20) for a in closes},
 'shadow_asym_20d':{a:shadow_asym(ohlc[a],20) for a in closes},
 'body_pos_20d':{a:body_pos(ohlc[a],20) for a in closes},
}
