    cands["dollar_vol_trend_20_120"] = {a: dollar_vol_trend(closes[a], vol[a], 20, 120) for a in closes if a in vol}
    cands["rolling_second_moment_20"] = {a: rolling_second_moment(s, 20) for a, s in closes.items()}

